1	// Server-side quote/creation path for CUSTOM VPS + game-server specs — plain
2	// module (not "use server"), mirroring lib/order.ts / lib/game-order.ts: it does
3	// real DB reads/writes but is called FROM "use server" actions that own the
4	// session check (lib/actions-custom-plan.ts), never exported to the network
5	// directly (see lib/order.ts's serverLimitError doc for why that split matters).
6	//
7	// The pure formula/guardrail math lives in lib/custom-plan-pricing.ts (no DB, so
8	// the client-side deploy wizards can price a slider move instantly); this file
9	// wraps it with the DB-backed floor/ceiling/rate resolution and the REAL
10	// capacity check, then creates the one-off `Plan` (+ `GamePlan`, for a game
11	// order) row a custom order actually buys.
12	import { db } from "./db";
13	import { getSettingInt } from "./settings";
14	import { extraDiskPerGbCents } from "./disk-expand";
15	import { capacityCheckRamMB, diskCapacityCheck } from "./capacity";
16	import { scheduleNode } from "./node-capacity";
17	import {
18	  type CustomPlanCeiling,
19	  type CustomPlanFloor,
20	  type CustomPlanRates,
21	  type CustomPlanSpec,
22	  CUSTOM_PLAN_DEFAULT_CEILING,
23	  CUSTOM_PLAN_DEFAULT_RATES,
24	  CUSTOM_PLAN_SORT_ORDER,
25	  computeCustomPlanPriceCents,
26	  customPlanName,
27	  customPlanSlug,
28	  validateCustomPlanSpec,
29	} from "./custom-plan-pricing";
30	
31	export { CUSTOM_PLAN_SORT_ORDER } from "./custom-plan-pricing";
32	
33	export class CustomPlanError extends Error {}
34	
35	/**
36	 * Sort-order convention already established by the ONE pre-existing manual
37	 * precedent (a "Custom 4 vCPU / 8 GB" Plan row, `sortOrder: 999, active: false`,
38	 * created before this feature existed for a one-off customer accommodation).
39	 * `sortOrder < CATALOG_SORT_ORDER_CEILING` is the live premade VPS ladder;
40	 * 900-903 are NxCloud's backing plans (also `active: false` — see prisma/schema.prisma's
41	 * comment on `Plan.nxcloudPlans`); `CUSTOM_PLAN_SORT_ORDER` (999) is reserved for
42	 * one-off custom rows. Both ranges keep `customPlanFloor` below from ever picking
43	 * up an NxCloud sizing plan or (worse) a PREVIOUS custom order's own Plan row as
44	 * "Max".
45	 */
46	const CATALOG_SORT_ORDER_CEILING = 900;
47	
48	/**
49	 * The floor every custom spec must clear: the current top-priced ACTIVE premade
50	 * VPS plan (today, Max). Read live from the DB rather than hardcoded, so a future
51	 * catalog change (a new tier added above Max) is picked up automatically with no
52	 * code change here.
53	 */
54	export async function customPlanFloor(): Promise<CustomPlanFloor> {
55	  const top = await db.plan.findFirst({
56	    where: { active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
57	    orderBy: { priceCents: "desc" },
58	  });
59	  if (!top) throw new CustomPlanError("No base plan is configured yet — please contact support.");
60	  return {
61	    cpuCores: top.cpuCores,
62	    ramMB: top.ramMB,
63	    diskGB: top.diskGB,
64	    priceCents: top.priceCents,
65	    bandwidthTB: top.bandwidthTB,
66	  };
67	}
68	
69	/** Admin-tunable platform-wide ceiling (lib/settings.ts custom_plan_max_*). */
70	export async function customPlanCeiling(): Promise<CustomPlanCeiling> {
71	  const [maxCpuCores, maxRamGB, maxDiskGB] = await Promise.all([
72	    getSettingInt("custom_plan_max_cpu_cores", CUSTOM_PLAN_DEFAULT_CEILING.maxCpuCores),
73	    getSettingInt("custom_plan_max_ram_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxRamMB / 1024),
74	    getSettingInt("custom_plan_max_disk_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxDiskGB),
75	  ]);
76	  return { maxCpuCores, maxRamMB: maxRamGB * 1024, maxDiskGB };
77	}
78	
79	/** Admin-tunable per-unit rates. Disk reuses `extraDiskPerGbCents()` — the SAME
80	 *  $/GB the extra-disk upsell already charges on a premade plan — see the
81	 *  derivation comment on CUSTOM_PLAN_DEFAULT_RATES for why. */
82	export async function customPlanRates(): Promise<CustomPlanRates> {
83	  const [perVcpuCents, perRamGbCents, perDiskGbCents] = await Promise.all([
84	    getSettingInt("custom_plan_per_vcpu_cents", CUSTOM_PLAN_DEFAULT_RATES.perVcpuCents),
85	    getSettingInt("custom_plan_per_ram_gb_cents", CUSTOM_PLAN_DEFAULT_RATES.perRamGbCents),
86	    extraDiskPerGbCents(),
87	  ]);
88	  return { perVcpuCents, perRamGbCents, perDiskGbCents };
89	}
90	
91	export type CustomPlanQuote =
92	  | { ok: true; floor: CustomPlanFloor; ceiling: CustomPlanCeiling; rates: CustomPlanRates; priceCents: number }
93	  | { ok: false; reason: string; floor: CustomPlanFloor; ceiling: CustomPlanCeiling };
94	
95	/** Validate + price a custom spec without creating anything. Never throws — a bad
96	 *  spec comes back `{ ok: false, reason }` so the wizard can show it inline. */
97	export async function customPlanQuote(spec: CustomPlanSpec): Promise<CustomPlanQuote> {
98	  const [floor, ceiling, rates] = await Promise.all([customPlanFloor(), customPlanCeiling(), customPlanRates()]);
99	  const v = validateCustomPlanSpec(spec, floor, ceiling);
100	  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };
101	  const priceCents = computeCustomPlanPriceCents(spec, floor, rates);
102	  return { ok: true, floor, ceiling, rates, priceCents };
103	}
104	
105	/**
106	 * The REAL, pre-checkout capacity check — reuses the exact oversell guards
107	 * lib/order.ts placeOrder / lib/game-order.ts placeGameOrder already run for
108	 * every premade-plan order (capacityCheckRamMB mirrors capacityCheck;
109	 * diskCapacityCheck is the identical function). A custom spec can ask for more
110	 * RAM than ANY catalog plan, so it must be screened the same way — this is not
111	 * a second, weaker guard, it's the same one with a raw RAM/disk number instead
112	 * of a `Plan` row backing it.
113	 */
114	export async function customPlanCapacityCheck(spec: CustomPlanSpec): Promise<{ ok: boolean; reason?: string }> {
115	  const ramOk = await capacityCheckRamMB(spec.ramMB);
116	  if (!ramOk.ok) return ramOk;
117	  // Which node WOULD take this — same scheduler VPS/game orders use — so the disk
118	  // check below runs against a real candidate node's pool, not "any node".
119	  const node = await scheduleNode(spec.ramMB);
120	  if (!node) {
121	    return { ok: false, reason: "No node currently has room for a server this size. Please contact support." };
122	  }
123	  return diskCapacityCheck(node.id, spec.diskGB);
124	}
125	
126	/** 6-char alnum suffix — matches the one pre-existing manual precedent's slug
127	 *  shape ("custom-4c8g-hmcebh"). */
128	function randSuffix(n = 6): string {
129	  return Math.random().toString(36).slice(2, 2 + n);
130	}
131	
132	export type CreatedCustomPlan = {
133	  id: string;
134	  name: string;
135	  cpuCores: number;
136	  ramMB: number;
137	  diskGB: number;
138	  bandwidthTB: number;
139	  priceCents: number;
140	  storageTier: string;
141	};
142	
143	/**
144	 * Create ONE real `Plan` row for this exact spec — the same manual-accommodation
145	 * pattern already proven in production once (see the sort-order doc comment
146	 * above), now automated. Re-validates guardrails AND capacity from scratch (a
147	 * client-supplied price/spec is never trusted for money — mirrors every other
148	 * quote→place split in this codebase) before writing anything.
149	 *
150	 * Created INACTIVE with `sortOrder: 999` so it NEVER appears in any catalog query
151	 * (every page that lists plans filters `active: true` — see
152	 * app/dashboard/deploy/page.tsx) — it exists solely to be the ONE plan this ONE
153	 * order's Server row points at. From here on, every downstream money path
154	 * (lib/order.ts orderQuote/placeOrder, lib/resize.ts, lib/renewal-charge.ts,
155	 * lib/capacity.ts, admin displays) reads straight off the `Plan` relation exactly
156	 * like it does for a premade plan — no special-casing needed anywhere else.
157	 */
158	export async function createCustomPlan(spec: CustomPlanSpec): Promise<CreatedCustomPlan> {
159	  const quote = await customPlanQuote(spec);
160	  if (!quote.ok) throw new CustomPlanError(quote.reason);
161	  const cap = await customPlanCapacityCheck(spec);
162	  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");
163	
164	  let lastErr: unknown;
165	  for (let attempt = 0; attempt < 3; attempt++) {
166	    try {
167	      const plan = await db.plan.create({
168	        data: {
169	          slug: customPlanSlug(spec, randSuffix()),
170	          name: customPlanName(spec),
171	          cpuCores: spec.cpuCores,
172	          ramMB: spec.ramMB,
173	          diskGB: spec.diskGB,
174	          bandwidthTB: quote.floor.bandwidthTB,
175	          priceCents: quote.priceCents,
176	          storageTier: "nvme",
177	          active: false,
178	          sortOrder: CUSTOM_PLAN_SORT_ORDER,
179	        },
180	      });
181	      return {
182	        id: plan.id,
183	        name: plan.name,
184	        cpuCores: plan.cpuCores,
185	        ramMB: plan.ramMB,
186	        diskGB: plan.diskGB,
187	        bandwidthTB: plan.bandwidthTB,
188	        priceCents: plan.priceCents,
189	        storageTier: plan.storageTier,
190	      };
191	    } catch (e) {
192	      lastErr = e; // near-impossible slug collision (6-char random suffix) — retry once or twice
193	    }
194	  }
195	  throw lastErr instanceof Error ? lastErr : new CustomPlanError("Could not create the custom plan — please try again.");
196	}
197	
198	export type CreatedCustomGamePlan = {
199	  plan: CreatedCustomPlan;
200	  gamePlanId: string;
201	  name: string;
202	  priceCents: number;
203	  slots: number | null;
204	};
205	
206	/**
207	 * Game analogue of `createCustomPlan`: also creates the `GamePlan` tier that
208	 * rides on top of the freshly-created base `Plan`, exactly like every premade
209	 * game tier already does (`GamePlan.basePlanId`) — see prisma/seed-gameplans.ts.
210	 * Priced at the SAME cents the base custom Plan would cost; a custom order has
211	 * no admin in the loop to hand-pick a cheaper flat game price the way premade
212	 * tiers sometimes are (see lib/resize.ts's comment on game tiers typically being
213	 * sold below their base plan's price), so charging exactly the formula price is
214	 * the safe, unambiguous default.
215	 */
216	export async function createCustomGamePlan(opts: {
217	  spec: CustomPlanSpec;
218	  gameFamily: string;
219	  players?: number | null;
220	}): Promise<CreatedCustomGamePlan> {
221	  // TEMPORARY GATE (2026-09-29): this reuses createCustomPlan's pure VPS
222	  // per-vCPU/per-RAM-GB rates unmodified for a GAME order, with no game-specific
223	  // premium at all. Confirmed against Rust's own live tier ladder: Rust's real
224	  // per-RAM-GB delta is roughly $5/GB; the VPS rate this charges is $1.02/GB —
225	  // a live custom Rust build was pricing at ~5x below what the game's own
226	  // catalog charges for the same resources. Blocking custom GAME orders here
227	  // until a per-family rate (derived from each game's own live tier ladder,
228	  // same disk-anchoring method custom-plan-pricing.ts already uses for VPS) is
229	  // in place. Plain VPS custom orders (createCustomPlan) are NOT affected —
230	  // the VPS rate is correct for VPS. See docs/DOCUMENTATION.md for the fix.
231	  throw new CustomPlanError(
232	    "Custom-sized servers for this game aren't available right now while we finish real pricing for it — please choose one of the plans above, or contact support for a custom quote.",
233	  );
234	  const plan = await createCustomPlan(opts.spec);
235	  const gp = await db.gamePlan.create({
236	    data: {
237	      gameFamily: opts.gameFamily,
238	      name: `${customPlanName(opts.spec)} (${opts.gameFamily})`,
239	      ramMB: plan.ramMB,
240	      cpuCores: plan.cpuCores,
241	      diskGB: plan.diskGB,
242	      slots: opts.players ?? null,
243	      priceCents: plan.priceCents,
244	      termMonths: 1,
245	      basePlanId: plan.id,
246	      active: false,
247	      sortOrder: CUSTOM_PLAN_SORT_ORDER,
248	    },
249	  });
250	  return { plan, gamePlanId: gp.id, name: gp.name, priceCents: gp.priceCents, slots: gp.slots };
251	}
252

"use server";

// "use server" surface for the custom-plan builder — every export here is a
// public network endpoint the moment it exists, so EVERY one starts with its own
// `requireUser()` (see lib/order.ts serverLimitError's doc for exactly why a
// helper that skips this is a HAZARD test/auth-lockouts.test.ts exists to catch).
//
// This module owns no money movement: `confirmCustomPlanAction` /
// `confirmCustomGamePlanAction` only create the one-off catalog row (a real
// `Plan`/`GamePlan`, see lib/custom-plan.ts) the customer then buys through the
// EXACT same `payAndDeploy` / `payAndDeployGame` path every premade plan uses —
// so the actual charge, capacity re-check, wallet debit and invoice are all
// handled by code this feature does not touch at all.
import { z } from "zod";
import { requireUser, assertNotImpersonating } from "./auth";
import { GAME_FAMILIES } from "./games";
import { annualDiscountPct } from "./annual-discount";
import { VPS_TERMS, vpsEffectiveMonthly } from "./billing-terms";
import {
  CustomPlanError,
  createCustomGamePlan,
  createCustomPlan,
  customPlanCapacityCheck,
  customPlanQuote,
} from "./custom-plan";

const specSchema = z.object({
  cpuCores: z.coerce.number().int().min(1).max(4096),
  ramMB: z.coerce.number().int().min(1).max(8 * 1024 * 1024),
  diskGB: z.coerce.number().int().min(1).max(1_000_000),
});

export type CustomPlanQuoteResult = {
  ok: boolean;
  error?: string;
  priceCents?: number;
  floor?: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number };
  ceiling?: { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
  capacityOk?: boolean;
  capacityReason?: string;
  /** Effective per-month rate at each billing term (1/12/24/36), worked out
   *  HERE through `vpsEffectiveMonthly` — the same term formula (and the same
   *  live admin annual-discount setting) orderQuote / gameOrderQuote charge
   *  through — so the Nexion wizard's custom card can print a term price
   *  without multiplying anything in the browser. */
  termMonthlyCents?: Record<number, number>;
};

/** Server-side per-term effective monthly rates for a custom monthly price. */
async function termMonthlyMatrix(monthlyCents: number): Promise<Record<number, number>> {
  const pct = await annualDiscountPct();
  const out: Record<number, number> = {};
  for (const t of VPS_TERMS) out[t.months] = vpsEffectiveMonthly(monthlyCents, t.months, pct);
  return out;
}

/**
 * Read-only live quote for the deploy wizard's custom-spec sliders — the
 * AUTHORITATIVE price/guardrail/capacity check, run right before the customer is
 * allowed to confirm a custom spec (the client-side computeCustomPlanPriceCents
 * call that drives the slider's live number as it moves is a preview only; this
 * is what actually gates the "Use this custom plan" button).
 */
export async function quoteCustomPlanAction(input: {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
}): Promise<CustomPlanQuoteResult> {
  await requireUser();
  const parsed = specSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
  const quote = await customPlanQuote(parsed.data);
  if (!quote.ok) return { ok: false, error: quote.reason, floor: quote.floor, ceiling: quote.ceiling };
  const [cap, termMonthlyCents] = await Promise.all([
    customPlanCapacityCheck(parsed.data),
    termMonthlyMatrix(quote.priceCents),
  ]);
  return {
    ok: true,
    priceCents: quote.priceCents,
    floor: quote.floor,
    ceiling: quote.ceiling,
    capacityOk: cap.ok,
    capacityReason: cap.reason,
    termMonthlyCents,
  };
}

export type ConfirmedCustomPlan = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
  /** Per-term effective monthly rate for THIS row's price — see CustomPlanQuoteResult. */
  termMonthlyCents: Record<number, number>;
};

/**
 * Create the one-off VPS `Plan` row for this exact spec. Called ONCE, when the
 * customer commits to their custom build (not on every slider tick) — the
 * returned plan's `id` then flows through the wizard's existing `planId` state
 * exactly like picking any premade plan card, so Location/Install/Access/Review/
 * Payment need no changes at all.
 */
export async function confirmCustomPlanAction(input: {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
}): Promise<{ ok: boolean; error?: string; plan?: ConfirmedCustomPlan }> {
  await requireUser();
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  const parsed = specSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
  try {
    const plan = await createCustomPlan(parsed.data);
    return { ok: true, plan: { ...plan, termMonthlyCents: await termMonthlyMatrix(plan.priceCents) } };
  } catch (e) {
    if (e instanceof CustomPlanError) return { ok: false, error: e.message };
    return { ok: false, error: "Couldn't set up that custom server. Please try again." };
  }
}

const gameConfirmSchema = specSchema.extend({
  gameFamily: z.enum(GAME_FAMILIES),
  players: z.coerce.number().int().min(1).max(1_000_000).optional(),
});

export type ConfirmedCustomGamePlan = {
  gamePlanId: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
  /** Per-term effective monthly rate for THIS tier's price — see CustomPlanQuoteResult. */
  termMonthlyCents: Record<number, number>;
};

/** Game analogue of `confirmCustomPlanAction` — creates the base `Plan` AND the
 *  `GamePlan` tier riding on it, returning the tier id the wizard drops straight
 *  into its existing `gamePlanId` hidden field. */
export async function confirmCustomGamePlanAction(input: {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  gameFamily: string;
  players?: number;
}): Promise<{ ok: boolean; error?: string; tier?: ConfirmedCustomGamePlan }> {
  await requireUser();
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  const parsed = gameConfirmSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
  try {
    const created = await createCustomGamePlan({
      spec: { cpuCores: parsed.data.cpuCores, ramMB: parsed.data.ramMB, diskGB: parsed.data.diskGB },
      gameFamily: parsed.data.gameFamily,
      players: parsed.data.players ?? null,
    });
    return {
      ok: true,
      tier: {
        gamePlanId: created.gamePlanId,
        name: created.name,
        cpuCores: created.plan.cpuCores,
        ramMB: created.plan.ramMB,
        diskGB: created.plan.diskGB,
        slots: created.slots,
        priceCents: created.priceCents,
        termMonths: 1,
        termMonthlyCents: await termMonthlyMatrix(created.priceCents),
      },
    };
  } catch (e) {
    if (e instanceof CustomPlanError) return { ok: false, error: e.message };
    return { ok: false, error: "Couldn't set up that custom server. Please try again." };
  }
}

