import fs from "fs";

const DISK_RATE = 10; // extra_disk_gb_price_cents default (confirmed no Setting override in prod)

const lines = fs.readFileSync("/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/gameplans.csv", "utf8")
  .trim().split("\n").map((l) => l.split(","));

const families = {};
for (const [fam, cpu, ram, disk, price] of lines) {
  (families[fam] ??= []).push({
    cpu: Number(cpu),
    ramGB: Number(ram) / 1024,
    disk: Number(disk),
    price: Number(price),
  });
}

// Sort each family by ramGB (should already be, but be safe) and compute deltas
const famDeltas = {}; // fam -> [{dcpu,dram,ddisk,dprice,remainder}]
for (const fam of Object.keys(families)) {
  const tiers = families[fam].slice().sort((a, b) => a.ramGB - b.ramGB || a.price - b.price);
  const deltas = [];
  for (let i = 1; i < tiers.length; i++) {
    const dcpu = tiers[i].cpu - tiers[i - 1].cpu;
    const dram = tiers[i].ramGB - tiers[i - 1].ramGB;
    const ddisk = tiers[i].disk - tiers[i - 1].disk;
    const dprice = tiers[i].price - tiers[i - 1].price;
    const remainder = dprice - DISK_RATE * ddisk;
    deltas.push({ dcpu, dram, ddisk, dprice, remainder });
  }
  famDeltas[fam] = deltas;
  families[fam] = tiers;
}

// FWL step 1: within-family residualize dcpu and remainder against dram (through origin),
// for families with >=2 deltas only (families with exactly 1 delta give a perfect fit,
// zero residual, and contribute no information toward the shared CPU rate).
let pooled = [];
for (const fam of Object.keys(famDeltas)) {
  const ds = famDeltas[fam];
  if (ds.length < 2) continue;
  const s_zz = ds.reduce((s, d) => s + d.dram * d.dram, 0);
  if (s_zz === 0) continue;
  const s_cz = ds.reduce((s, d) => s + d.dcpu * d.dram, 0);
  const s_pz = ds.reduce((s, d) => s + d.remainder * d.dram, 0);
  const coef_c = s_cz / s_zz;
  const coef_p = s_pz / s_zz;
  for (const d of ds) {
    const cpu_tilde = d.dcpu - coef_c * d.dram;
    const rem_tilde = d.remainder - coef_p * d.dram;
    pooled.push({ fam, cpu_tilde, rem_tilde });
  }
}

const s_cc = pooled.reduce((s, p) => s + p.cpu_tilde * p.cpu_tilde, 0);
const s_rc = pooled.reduce((s, p) => s + p.rem_tilde * p.cpu_tilde, 0);
const globalA = s_cc > 1e-9 ? s_rc / s_cc : null;

console.log("=== Pooled residual points feeding the global vCPU-rate fit ===");
console.log(`n points (from multi-delta families) = ${pooled.length}`);
console.log(`sum(cpu_tilde^2) = ${s_cc.toFixed(4)}, sum(rem_tilde*cpu_tilde) = ${s_rc.toFixed(4)}`);
console.log(`GLOBAL per-vCPU rate (a) = ${globalA?.toFixed(4)} cents/vCPU`);

// Show per-family joint (a,b) solve too, for families with exactly 2 deltas (exact 2x2 solve),
// purely as a DIAGNOSTIC to see how unstable independent per-family CPU fits would be.
console.log("\n=== DIAGNOSTIC: independent per-family joint (a,b) solve where possible (2 deltas => exact 2x2) ===");
for (const fam of Object.keys(famDeltas).sort()) {
  const ds = famDeltas[fam];
  if (ds.length !== 2) continue;
  const [d1, d2] = ds;
  // Solve [dcpu1 dram1; dcpu2 dram2] * [a;b] = [remainder1; remainder2]
  const det = d1.dcpu * d2.dram - d2.dcpu * d1.dram;
  if (Math.abs(det) < 1e-9) {
    console.log(`${fam}: SINGULAR (deltas proportional) — cannot solve independently`);
    continue;
  }
  const a = (d1.remainder * d2.dram - d2.remainder * d1.dram) / det;
  const b = (d1.dcpu * d2.remainder - d2.dcpu * d1.remainder) / det;
  console.log(`${fam}: a=${a.toFixed(2)}c/vcpu, b=${b.toFixed(2)}c/GB`);
}

// Now, using globalA, solve per-family RAM rate (b) via OLS through origin over ALL deltas
// (works uniformly whether the family has 1 or 2+ deltas).
console.log("\n=== FINAL per-family RAM rate using anchored global CPU rate + anchored disk rate ===");
const a = Math.round(globalA); // round to whole cents for a clean admin-settable constant
console.log(`Using rounded global vCPU rate a = ${a} cents/vCPU (raw fit: ${globalA.toFixed(3)})`);
console.log(`Using anchored disk rate = ${DISK_RATE} cents/GB (extra_disk_gb_price_cents)`);

const results = {};
for (const fam of Object.keys(famDeltas).sort()) {
  const ds = famDeltas[fam];
  const s_zz = ds.reduce((s, d) => s + d.dram * d.dram, 0);
  const s_yz = ds.reduce((s, d) => s + (d.remainder - a * d.dcpu) * d.dram, 0);
  const b = s_zz > 1e-9 ? s_yz / s_zz : null;
  results[fam] = { b, nDeltas: ds.length, tiers: families[fam] };
  console.log(`${fam.padEnd(16)} n=${ds.length}  b=${b?.toFixed(2)} c/GB RAM  ($${(b/100).toFixed(2)}/GB)`);
}

fs.writeFileSync(
  "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/rate-results.json",
  JSON.stringify({ globalA: a, rawGlobalA: globalA, diskRate: DISK_RATE, results }, null, 2)
);
console.log("\nWrote rate-results.json");

