  JPY: { symbol: "¥", code: "JPY" },
  CNY: { symbol: "¥", code: "CNY" },
  BRL: { symbol: "R$", code: "BRL" },
  ZAR: { symbol: "R", code: "ZAR" },
  CHF: { symbol: "CHF ", code: "CHF" },
  SEK: { symbol: "kr ", code: "SEK" },
  PLN: { symbol: "zł ", code: "PLN" },
  MXN: { symbol: "MX$", code: "MXN" },
  SGD: { symbol: "S$", code: "SGD" },
  AED: { symbol: "د.إ ", code: "AED" },
  // Southeast Asia (the ad-targeted markets — Vietnam, Philippines, etc.)
  VND: { symbol: "₫", code: "VND" },
  PHP: { symbol: "₱", code: "PHP" },
  THB: { symbol: "฿", code: "THB" },
  IDR: { symbol: "Rp ", code: "IDR" },
  MYR: { symbol: "RM ", code: "MYR" },
  // ── Comprehensive world coverage (all DISPLAY-only, USD stays the charge ccy) ──
  // East / Southeast / South Asia
  KRW: { symbol: "₩", code: "KRW" },
  HKD: { symbol: "HK$", code: "HKD" },
  TWD: { symbol: "NT$", code: "TWD" },
  MOP: { symbol: "MOP$", code: "MOP" },
  BND: { symbol: "B$", code: "BND" },
  PKR: { symbol: "₨", code: "PKR" },
  BDT: { symbol: "৳", code: "BDT" },
  LKR: { symbol: "Rs ", code: "LKR" },
  NPR: { symbol: "Rs ", code: "NPR" },
  MMK: { symbol: "K ", code: "MMK" },
  KHR: { symbol: "៛", code: "KHR" },
  LAK: { symbol: "₭", code: "LAK" },
  MVR: { symbol: "Rf ", code: "MVR" },
  MNT: { symbol: "₮", code: "MNT" },
  // Central Asia & Caucasus
  KZT: { symbol: "₸", code: "KZT" },
  UZS: { symbol: "UZS ", code: "UZS" },
  AZN: { symbol: "₼", code: "AZN" },
  GEL: { symbol: "₾", code: "GEL" },
  AMD: { symbol: "֏", code: "AMD" },
  AFN: { symbol: "؋", code: "AFN" },
  // Europe (non-euro)
  NOK: { symbol: "kr ", code: "NOK" },
  DKK: { symbol: "kr ", code: "DKK" },
  ISK: { symbol: "kr ", code: "ISK" },
  CZK: { symbol: "Kč ", code: "CZK" },
  HUF: { symbol: "Ft ", code: "HUF" },
  RON: { symbol: "lei ", code: "RON" },
  BGN: { symbol: "лв ", code: "BGN" },
  RSD: { symbol: "дин ", code: "RSD" },

  HNL: 24.8,
  NIO: 36.8,
  CRC: 520,
  JMD: 157,
  TTD: 6.8,
  XCD: 2.7,
  // Oceania (Pacific)
  FJD: 2.25,
  PGK: 3.9,
  XPF: 110,
  VUV: 119,
};

/**
 * Merge an admin JSON override (the `currency_rates` Setting) over the default
 * rate table. Pure and defensive: unparseable JSON, non-object payloads, unknown
 * currency codes, and non-positive / non-finite rates are all ignored, so a
 * fat-fingered override can only fail *safe* (fall back to the default rate),
 * never zero out or invert a price. USD is always pinned to 1.
 */
export function parseRatesOverride(json: string | null | undefined): Record<string, number> {
  const rates: Record<string, number> = { ...DEFAULT_CURRENCY_RATES };
  if (json && json.trim()) {
    try {
      const parsed = JSON.parse(json) as unknown;
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
          const code = k.trim().toUpperCase();
          const rate = typeof v === "number" ? v : Number(v);
          if (CURRENCIES[code] && Number.isFinite(rate) && rate > 0) rates[code] = rate;
        }
      }
    } catch {
      // Malformed override → defaults only. Never throws.
    }
  }
  rates.USD = 1;
  return rates;
}

