/**
 * Merge an admin JSON override (the `custom_plan_game_ram_rates_json` Setting) over
 * the derived default table. Pure and defensive — mirrors `parseRatesOverride`
 * (lib/currency.ts) exactly: unparseable JSON, a non-object payload, and any
 * non-positive/non-finite rate are all ignored so a fat-fingered override can only
 * fail SAFE (fall back to the derived default for that family), never zero out or
 * invert a game's price.
 */
export function parseGameFamilyRatesOverride(json: string | null | undefined): Record<string, number> {
  const rates: Record<string, number> = { ...CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS };
  if (json && json.trim()) {
    try {
      const parsed = JSON.parse(json) as unknown;
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
          const family = k.trim();
          const rate = typeof v === "number" ? v : Number(v);
          if (family && Number.isFinite(rate) && rate > 0) rates[family] = Math.round(rate);
        }
      }
    } catch {
      // Malformed override -> defaults only. Never throws.
    }
  }
  return rates;
}

