/** The one real, live tier this family's custom price is extrapolated FROM — its own
 *  biggest active `GamePlan` row (lib/custom-plan.ts resolves this from the DB; kept
 *  as a small anchor type here so the pure pricing math stays DB-free). */
export type CustomGamePlanAnchor = { cpuCores: number; ramMB: number; diskGB: number; priceCents: number };

/**
 * The floor a custom GAME spec must clear — the VPS floor (today, Max) widened on any
 * dimension where this family's OWN top real tier is already bigger. Without this
 * widening, a family whose premade ladder already runs hotter than Max on some
 * dimension (e.g. Squad's top tier is 10 vCPU / 32 GB — both above Max's 4/16) could
 * have a "custom" order that is SMALLER than its own biggest premade tier on that
 * dimension while still clearing the generic VPS floor, which would both undercut that
 * tier's own price and violate the monotonic-upgrade invariant every other resize path
 * in this codebase depends on (see lib/resize.ts). `priceCents`/`bandwidthTB` stay the
 * VPS floor's — the anti-undercut price anchor is deliberately still the platform-wide
 * number here; `computeCustomGamePlanPriceCents` below does its own, family-curve-aware
 * pricing and re-clamps against this same VPS floor price directly.
 */
export function gameCustomFloor(vpsFloor: CustomPlanFloor, topTier: CustomGamePlanAnchor): CustomPlanFloor {
  return {
    cpuCores: Math.max(vpsFloor.cpuCores, topTier.cpuCores),
    ramMB: Math.max(vpsFloor.ramMB, topTier.ramMB),
    diskGB: Math.max(vpsFloor.diskGB, topTier.diskGB),
    priceCents: vpsFloor.priceCents,
    bandwidthTB: vpsFloor.bandwidthTB,
  };
}

/**
 * The custom GAME price: this family's own top real tier's price, plus its own
 * per-vCPU/per-RAM-GB/per-disk-GB rate for whatever the spec asks beyond that tier —
 * literally extending the family's own real price curve past its last real data point,
 * rather than starting over from the flat VPS Max price the way the old (buggy)
 * behavior did. `dCpu`/`dRamGB`/`dDiskGB` can be negative on an individual dimension
 * (e.g. a spec at exactly `gameCustomFloor` for a family whose top tier already beat
 * Max on RAM will have `dRamGB` <= 0 there) — that's fine, it's still one evaluation of
 * the same straight line; only the FINAL price is clamped.
 *
 * Double-clamped, deliberately redundant with `gameCustomFloor`'s widening above: never
 * at-or-below the platform VPS-Max price (the same anti-undercut guarantee
 * `computeCustomPlanPriceCents` enforces for VPS), AND never at-or-below this family's
 * OWN top real tier's price. A caller that validated the spec against
 * `gameCustomFloor` first can never actually hit either clamp — they exist so this
 * function is safe on its own, not just in combination with that validation.
 */
export function computeCustomGamePlanPriceCents(
  spec: CustomPlanSpec,
  topTier: CustomGamePlanAnchor,
  rates: CustomPlanRates,
  vpsFloorPriceCents: number,
): number {
  const dCpu = spec.cpuCores - topTier.cpuCores;
  const dRamGB = (spec.ramMB - topTier.ramMB) / 1024;
  const dDiskGB = spec.diskGB - topTier.diskGB;
  const raw =
