/**
 * Genre-average fallback for a game family that has real `GamePlan` tiers but not
 * enough of them (exactly one, so a $/RAM-GB slope has no second data point to derive
 * from — see lib/custom-plan-pricing.ts's derivation comment). NOT hit by anything in
 * the live catalog today (every family with any tiers has at least 2 — see that same
 * comment), but a new family could plausibly launch with just one tier seeded before a
 * second ships, and this keeps that case priced (clearly flagged as an estimate)
 * instead of silently falling through to `CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS`'s
 * `undefined` and gating the family for a reason that isn't actually "we have zero
 * data" — we have a real anchor tier, just not a real slope.
 *
 * Averages the derived (non-estimated) rates of every OTHER family that shares at
 * least one genre tag (lib/games.ts GAME_GENRES) with this one; a family with no genre
 * tag, or no genre-mates in the table, falls back to the average of the WHOLE table —
 * still grounded in real derived data, just not narrowed by genre. Never fabricated
 * from nothing: this only ever runs for a family that already has one real tier
 * anchoring its base price, and only picks the SLOPE from other real games' data.
 */
export function estimatedGameFamilyRamRateCents(
  family: string,
  ramRatesCents: Record<string, number>,
): { cents: number; estimated: true; basis: string } {
  const genres = GAME_GENRES[family as GameFamily];
  const allRates = Object.entries(ramRatesCents).filter(([f]) => f !== family);
  const genreMates = genres?.length
    ? allRates.filter(([f]) => GAME_GENRES[f as GameFamily]?.some((g) => genres.includes(g)))
    : [];
  const pool = genreMates.length ? genreMates : allRates;
  const avg = pool.reduce((s, [, c]) => s + c, 0) / (pool.length || 1);
  return {
    cents: Math.round(avg),
    estimated: true,
    basis: genreMates.length
      ? `genre average (${genreMates.length} family/families sharing ${genres!.join("/")})`
      : "platform-wide average across all derived game families",
  };
}

/**
 * Admin-tunable per-family GAME custom-build rates: the shared per-vCPU rate
 * (`custom_plan_game_per_vcpu_cents`) plus this specific family's per-RAM-GB rate
 * (looked up in the `custom_plan_game_ram_rates_json` override merged over
 * CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS — see lib/custom-plan-pricing.ts). Disk reuses
 * `extraDiskPerGbCents()`, same as `customPlanRates()` above.
 *
 * Returns `null` when this family has no grounded rate at all (absent from the table
 * AND not resolvable via the genre-average fallback because it has no real anchor
 * tier to begin with) — the caller (`createCustomGamePlan`) treats that as "stay
 * gated," never as "charge zero."
 */
export async function customGamePlanRates(
  gameFamily: string,
): Promise<{ rates: CustomPlanRates; estimated: boolean; basis?: string } | null> {
  const [perVcpuCents, ramRatesJson, perDiskGbCents] = await Promise.all([
    getSettingInt("custom_plan_game_per_vcpu_cents", CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS),
    getSetting("custom_plan_game_ram_rates_json", ""),
    extraDiskPerGbCents(),
  ]);
  const ramRatesCents = parseGameFamilyRatesOverride(ramRatesJson);
  const direct = ramRatesCents[gameFamily];
  if (direct !== undefined) {
    return { rates: { perVcpuCents, perRamGbCents: direct, perDiskGbCents }, estimated: false };
  }
  const est = estimatedGameFamilyRamRateCents(gameFamily, ramRatesCents);
  return {
    rates: { perVcpuCents, perRamGbCents: est.cents, perDiskGbCents },
    estimated: true,
    basis: est.basis,
  };
}

