 * methodology) — so a custom build is a genuine continuation of THIS game's own
 * pricing curve, not the platform's generic VPS curve wearing a game's name. The
 * floor a spec must clear is similarly widened per-family (`gameCustomFloor`) so a
 * "custom" order can never be smaller, on any dimension, than this family's own
 * biggest premade tier.
 *
 * Still gated (throws) for a family with ZERO live tiers to anchor from at all —
 * see `customGamePlanRates`'s doc and lib/custom-plan-pricing.ts's derivation
 * comment for exactly which families that is and why (as of 2026-09-29:
 * `schedule1` and the four `plutonium*` variants — none of which can be bought as a
 * premade tier either today, so this changes nothing about their sellability).
 */
export async function createCustomGamePlan(opts: {
  spec: CustomPlanSpec;
  gameFamily: string;
  players?: number | null;
}): Promise<CreatedCustomGamePlan> {
  const topTier = await db.gamePlan.findFirst({
    where: { gameFamily: opts.gameFamily, active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
    orderBy: { priceCents: "desc" },
  });
  if (!topTier) {
    throw new CustomPlanError(
      "Custom-sized servers for this game aren't available yet — there's no pricing catalog to build a custom quote from. Please contact support.",
    );
  }
  const anchor: CustomGamePlanAnchor = {
    cpuCores: topTier.cpuCores,
    ramMB: topTier.ramMB,
    diskGB: topTier.diskGB,
    priceCents: topTier.priceCents,
  };

  const [vpsFloor, ceiling, gameRates] = await Promise.all([
    customPlanFloor(),
    customPlanCeiling(),
    customGamePlanRates(opts.gameFamily),
  ]);
  if (!gameRates) {
    throw new CustomPlanError(
      "Custom-sized servers for this game aren't available yet — please contact support for a custom quote.",
    );
  }

  const floor = gameCustomFloor(vpsFloor, anchor);
  const v = validateCustomPlanSpec(opts.spec, floor, ceiling);
  if (!v.ok) throw new CustomPlanError(v.reason);
  const cap = await customPlanCapacityCheck(opts.spec);
  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");

  const priceCents = computeCustomGamePlanPriceCents(opts.spec, anchor, gameRates.rates, vpsFloor.priceCents);
  const plan = await createCustomPlanRow(opts.spec, priceCents, vpsFloor.bandwidthTB);
  const gp = await db.gamePlan.create({
    data: {
      gameFamily: opts.gameFamily,
      name: `${customPlanName(opts.spec)} (${opts.gameFamily})`,
      ramMB: plan.ramMB,
      cpuCores: plan.cpuCores,
      diskGB: plan.diskGB,
      slots: opts.players ?? null,
      priceCents: plan.priceCents,
      termMonths: 1,
      basePlanId: plan.id,
      active: false,
      sortOrder: CUSTOM_PLAN_SORT_ORDER,
    },
  });
  return { plan, gamePlanId: gp.id, name: gp.name, priceCents: gp.priceCents, slots: gp.slots };
}

