1	// Server-side quote/creation path for CUSTOM VPS + game-server specs — plain
2	// module (not "use server"), mirroring lib/order.ts / lib/game-order.ts: it does
3	// real DB reads/writes but is called FROM "use server" actions that own the
4	// session check (lib/actions-custom-plan.ts), never exported to the network
5	// directly (see lib/order.ts's serverLimitError doc for why that split matters).
6	//
7	// The pure formula/guardrail math lives in lib/custom-plan-pricing.ts (no DB, so
8	// the client-side deploy wizards can price a slider move instantly); this file
9	// wraps it with the DB-backed floor/ceiling/rate resolution and the REAL
10	// capacity check, then creates the one-off `Plan` (+ `GamePlan`, for a game
11	// order) row a custom order actually buys.
12	import { db } from "./db";
13	import { getSetting, getSettingInt } from "./settings";
14	import { extraDiskPerGbCents } from "./disk-expand";
15	import { capacityCheckRamMB, diskCapacityCheck } from "./capacity";
16	import { scheduleNode } from "./node-capacity";
17	import { GAME_GENRES, type GameFamily } from "./games";
18	import {
19	  type CustomGamePlanAnchor,
20	  type CustomPlanCeiling,
21	  type CustomPlanFloor,
22	  type CustomPlanRates,
23	  type CustomPlanSpec,
24	  CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS,
25	  CUSTOM_PLAN_DEFAULT_CEILING,
26	  CUSTOM_PLAN_DEFAULT_RATES,
27	  CUSTOM_PLAN_SORT_ORDER,
28	  computeCustomGamePlanPriceCents,
29	  computeCustomPlanPriceCents,
30	  customPlanName,
31	  customPlanSlug,
32	  gameCustomFloor,
33	  parseGameFamilyRatesOverride,
34	  validateCustomPlanSpec,
35	} from "./custom-plan-pricing";
36	
37	export { CUSTOM_PLAN_SORT_ORDER } from "./custom-plan-pricing";
38	
39	export class CustomPlanError extends Error {}
40	
41	/**
42	 * Sort-order convention already established by the ONE pre-existing manual
43	 * precedent (a "Custom 4 vCPU / 8 GB" Plan row, `sortOrder: 999, active: false`,
44	 * created before this feature existed for a one-off customer accommodation).
45	 * `sortOrder < CATALOG_SORT_ORDER_CEILING` is the live premade VPS ladder;
46	 * 900-903 are NxCloud's backing plans (also `active: false` — see prisma/schema.prisma's
47	 * comment on `Plan.nxcloudPlans`); `CUSTOM_PLAN_SORT_ORDER` (999) is reserved for
48	 * one-off custom rows. Both ranges keep `customPlanFloor` below from ever picking
49	 * up an NxCloud sizing plan or (worse) a PREVIOUS custom order's own Plan row as
50	 * "Max".
51	 */
52	const CATALOG_SORT_ORDER_CEILING = 900;
53	
54	/**
55	 * The floor every custom spec must clear: the current top-priced ACTIVE premade
56	 * VPS plan (today, Max). Read live from the DB rather than hardcoded, so a future
57	 * catalog change (a new tier added above Max) is picked up automatically with no
58	 * code change here.
59	 */
60	export async function customPlanFloor(): Promise<CustomPlanFloor> {
61	  const top = await db.plan.findFirst({
62	    where: { active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
63	    orderBy: { priceCents: "desc" },
64	  });
65	  if (!top) throw new CustomPlanError("No base plan is configured yet — please contact support.");
66	  return {
67	    cpuCores: top.cpuCores,
68	    ramMB: top.ramMB,
69	    diskGB: top.diskGB,
70	    priceCents: top.priceCents,
71	    bandwidthTB: top.bandwidthTB,
72	  };
73	}
74	
75	/** Admin-tunable platform-wide ceiling (lib/settings.ts custom_plan_max_*). */
76	export async function customPlanCeiling(): Promise<CustomPlanCeiling> {
77	  const [maxCpuCores, maxRamGB, maxDiskGB] = await Promise.all([
78	    getSettingInt("custom_plan_max_cpu_cores", CUSTOM_PLAN_DEFAULT_CEILING.maxCpuCores),
79	    getSettingInt("custom_plan_max_ram_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxRamMB / 1024),
80	    getSettingInt("custom_plan_max_disk_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxDiskGB),
81	  ]);
82	  return { maxCpuCores, maxRamMB: maxRamGB * 1024, maxDiskGB };
83	}
84	
85	/** Admin-tunable per-unit rates. Disk reuses `extraDiskPerGbCents()` — the SAME
86	 *  $/GB the extra-disk upsell already charges on a premade plan — see the
87	 *  derivation comment on CUSTOM_PLAN_DEFAULT_RATES for why. */
88	export async function customPlanRates(): Promise<CustomPlanRates> {
89	  const [perVcpuCents, perRamGbCents, perDiskGbCents] = await Promise.all([
90	    getSettingInt("custom_plan_per_vcpu_cents", CUSTOM_PLAN_DEFAULT_RATES.perVcpuCents),
91	    getSettingInt("custom_plan_per_ram_gb_cents", CUSTOM_PLAN_DEFAULT_RATES.perRamGbCents),
92	    extraDiskPerGbCents(),
93	  ]);
94	  return { perVcpuCents, perRamGbCents, perDiskGbCents };
95	}
96	
97	/**
98	 * Genre-average fallback for a game family that has real `GamePlan` tiers but not
99	 * enough of them (exactly one, so a $/RAM-GB slope has no second data point to derive
100	 * from — see lib/custom-plan-pricing.ts's derivation comment). NOT hit by anything in
101	 * the live catalog today (every family with any tiers has at least 2 — see that same
102	 * comment), but a new family could plausibly launch with just one tier seeded before a
103	 * second ships, and this keeps that case priced (clearly flagged as an estimate)
104	 * instead of silently falling through to `CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS`'s
105	 * `undefined` and gating the family for a reason that isn't actually "we have zero
106	 * data" — we have a real anchor tier, just not a real slope.
107	 *
108	 * Averages the derived (non-estimated) rates of every OTHER family that shares at
109	 * least one genre tag (lib/games.ts GAME_GENRES) with this one; a family with no genre
110	 * tag, or no genre-mates in the table, falls back to the average of the WHOLE table —
111	 * still grounded in real derived data, just not narrowed by genre. Never fabricated
112	 * from nothing: this only ever runs for a family that already has one real tier
113	 * anchoring its base price, and only picks the SLOPE from other real games' data.
114	 */
115	export function estimatedGameFamilyRamRateCents(
116	  family: string,
117	  ramRatesCents: Record<string, number>,
118	): { cents: number; estimated: true; basis: string } {
119	  const genres = GAME_GENRES[family as GameFamily];
120	  const allRates = Object.entries(ramRatesCents).filter(([f]) => f !== family);
121	  const genreMates = genres?.length
122	    ? allRates.filter(([f]) => GAME_GENRES[f as GameFamily]?.some((g) => genres.includes(g)))
123	    : [];
124	  const pool = genreMates.length ? genreMates : allRates;
125	  const avg = pool.reduce((s, [, c]) => s + c, 0) / (pool.length || 1);
126	  return {
127	    cents: Math.round(avg),
128	    estimated: true,
129	    basis: genreMates.length
130	      ? `genre average (${genreMates.length} family/families sharing ${genres!.join("/")})`
131	      : "platform-wide average across all derived game families",
132	  };
133	}
134	
135	/**
136	 * Admin-tunable per-family GAME custom-build rates: the shared per-vCPU rate
137	 * (`custom_plan_game_per_vcpu_cents`) plus this specific family's per-RAM-GB rate
138	 * (looked up in the `custom_plan_game_ram_rates_json` override merged over
139	 * CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS — see lib/custom-plan-pricing.ts). Disk reuses
140	 * `extraDiskPerGbCents()`, same as `customPlanRates()` above.
141	 *
142	 * Returns `null` when this family has no grounded rate at all (absent from the table
143	 * AND not resolvable via the genre-average fallback because it has no real anchor
144	 * tier to begin with) — the caller (`createCustomGamePlan`) treats that as "stay
145	 * gated," never as "charge zero."
146	 */
147	export async function customGamePlanRates(
148	  gameFamily: string,
149	): Promise<{ rates: CustomPlanRates; estimated: boolean; basis?: string } | null> {
150	  const [perVcpuCents, ramRatesJson, perDiskGbCents] = await Promise.all([
151	    getSettingInt("custom_plan_game_per_vcpu_cents", CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS),
152	    getSetting("custom_plan_game_ram_rates_json", ""),
153	    extraDiskPerGbCents(),
154	  ]);
155	  const ramRatesCents = parseGameFamilyRatesOverride(ramRatesJson);
156	  const direct = ramRatesCents[gameFamily];
157	  if (direct !== undefined) {
158	    return { rates: { perVcpuCents, perRamGbCents: direct, perDiskGbCents }, estimated: false };
159	  }
160	  const est = estimatedGameFamilyRamRateCents(gameFamily, ramRatesCents);
161	  return {
162	    rates: { perVcpuCents, perRamGbCents: est.cents, perDiskGbCents },
163	    estimated: true,
164	    basis: est.basis,
165	  };
166	}
167	
168	export type CustomPlanQuote =
169	  | { ok: true; floor: CustomPlanFloor; ceiling: CustomPlanCeiling; rates: CustomPlanRates; priceCents: number }
170	  | { ok: false; reason: string; floor: CustomPlanFloor; ceiling: CustomPlanCeiling };
171	
172	/** Validate + price a custom spec without creating anything. Never throws — a bad
173	 *  spec comes back `{ ok: false, reason }` so the wizard can show it inline. */
174	export async function customPlanQuote(spec: CustomPlanSpec): Promise<CustomPlanQuote> {
175	  const [floor, ceiling, rates] = await Promise.all([customPlanFloor(), customPlanCeiling(), customPlanRates()]);
176	  const v = validateCustomPlanSpec(spec, floor, ceiling);
177	  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };
178	  const priceCents = computeCustomPlanPriceCents(spec, floor, rates);
179	  return { ok: true, floor, ceiling, rates, priceCents };
180	}
181	
182	/**
183	 * The REAL, pre-checkout capacity check — reuses the exact oversell guards
184	 * lib/order.ts placeOrder / lib/game-order.ts placeGameOrder already run for
185	 * every premade-plan order (capacityCheckRamMB mirrors capacityCheck;
186	 * diskCapacityCheck is the identical function). A custom spec can ask for more
187	 * RAM than ANY catalog plan, so it must be screened the same way — this is not
188	 * a second, weaker guard, it's the same one with a raw RAM/disk number instead
189	 * of a `Plan` row backing it.
190	 */
191	export async function customPlanCapacityCheck(spec: CustomPlanSpec): Promise<{ ok: boolean; reason?: string }> {
192	  const ramOk = await capacityCheckRamMB(spec.ramMB);
193	  if (!ramOk.ok) return ramOk;
194	  // Which node WOULD take this — same scheduler VPS/game orders use — so the disk
195	  // check below runs against a real candidate node's pool, not "any node".
196	  const node = await scheduleNode(spec.ramMB);
197	  if (!node) {
198	    return { ok: false, reason: "No node currently has room for a server this size. Please contact support." };
199	  }
200	  return diskCapacityCheck(node.id, spec.diskGB);
201	}
202	
203	/** 6-char alnum suffix — matches the one pre-existing manual precedent's slug
204	 *  shape ("custom-4c8g-hmcebh"). */
205	function randSuffix(n = 6): string {
206	  return Math.random().toString(36).slice(2, 2 + n);
207	}
208	
209	export type CreatedCustomPlan = {
210	  id: string;
211	  name: string;
212	  cpuCores: number;
213	  ramMB: number;
214	  diskGB: number;
215	  bandwidthTB: number;
216	  priceCents: number;
217	  storageTier: string;
218	};
219	
220	/**
221	 * Create ONE real `Plan` row for an exact spec+price — the same manual-accommodation
222	 * pattern already proven in production once (see the sort-order doc comment above),
223	 * now automated. Shared by `createCustomPlan` (VPS) and `createCustomGamePlan`
224	 * (game) below — the retry-on-slug-collision loop and row shape are identical, only
225	 * how `priceCents` gets computed differs between the two callers.
226	 *
227	 * Created INACTIVE with `sortOrder: 999` so it NEVER appears in any catalog query
228	 * (every page that lists plans filters `active: true` — see
229	 * app/dashboard/deploy/page.tsx) — it exists solely to be the ONE plan this ONE
230	 * order's Server row points at. From here on, every downstream money path
231	 * (lib/order.ts orderQuote/placeOrder, lib/resize.ts, lib/renewal-charge.ts,
232	 * lib/capacity.ts, admin displays) reads straight off the `Plan` relation exactly
233	 * like it does for a premade plan — no special-casing needed anywhere else.
234	 */
235	async function createCustomPlanRow(
236	  spec: CustomPlanSpec,
237	  priceCents: number,
238	  bandwidthTB: number,
239	): Promise<CreatedCustomPlan> {
240	  let lastErr: unknown;
241	  for (let attempt = 0; attempt < 3; attempt++) {
242	    try {
243	      const plan = await db.plan.create({
244	        data: {
245	          slug: customPlanSlug(spec, randSuffix()),
246	          name: customPlanName(spec),
247	          cpuCores: spec.cpuCores,
248	          ramMB: spec.ramMB,
249	          diskGB: spec.diskGB,
250	          bandwidthTB,
251	          priceCents,
252	          storageTier: "nvme",
253	          active: false,
254	          sortOrder: CUSTOM_PLAN_SORT_ORDER,
255	        },
256	      });
257	      return {
258	        id: plan.id,
259	        name: plan.name,
260	        cpuCores: plan.cpuCores,
261	        ramMB: plan.ramMB,
262	        diskGB: plan.diskGB,
263	        bandwidthTB: plan.bandwidthTB,
264	        priceCents: plan.priceCents,
265	        storageTier: plan.storageTier,
266	      };
267	    } catch (e) {
268	      lastErr = e; // near-impossible slug collision (6-char random suffix) — retry once or twice
269	    }
270	  }
271	  throw lastErr instanceof Error ? lastErr : new CustomPlanError("Could not create the custom plan — please try again.");
272	}
273	
274	/**
275	 * Re-validates guardrails AND capacity from scratch (a client-supplied price/spec is
276	 * never trusted for money — mirrors every other quote→place split in this codebase)
277	 * before writing anything, then hands off to `createCustomPlanRow`.
278	 */
279	export async function createCustomPlan(spec: CustomPlanSpec): Promise<CreatedCustomPlan> {
280	  const quote = await customPlanQuote(spec);
281	  if (!quote.ok) throw new CustomPlanError(quote.reason);
282	  const cap = await customPlanCapacityCheck(spec);
283	  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");
284	  return createCustomPlanRow(spec, quote.priceCents, quote.floor.bandwidthTB);
285	}
286	
287	export type CreatedCustomGamePlan = {
288	  plan: CreatedCustomPlan;
289	  gamePlanId: string;
290	  name: string;
291	  priceCents: number;
292	  slots: number | null;
293	};
294	
295	/**
296	 * Game analogue of `createCustomPlan`: also creates the `GamePlan` tier that rides on
297	 * top of the freshly-created base `Plan`, exactly like every premade game tier
298	 * already does (`GamePlan.basePlanId`) — see prisma/seed-gameplans.ts.
299	 *
300	 * REAL per-family pricing (2026-09-29, replacing the stop-gap throw that blocked
301	 * every custom game order — see docs/DOCUMENTATION.md). Unlike `createCustomPlan`,
302	 * the price here is NOT floor.priceCents + flat-VPS-rate * extra: it's this game
303	 * family's own top real `GamePlan` tier's price, extended by that family's own
304	 * per-vCPU/per-RAM-GB rate (lib/custom-plan-pricing.ts's
305	 * `computeCustomGamePlanPriceCents` — read its derivation comment for the full
306	 * methodology) — so a custom build is a genuine continuation of THIS game's own
307	 * pricing curve, not the platform's generic VPS curve wearing a game's name. The
308	 * floor a spec must clear is similarly widened per-family (`gameCustomFloor`) so a
309	 * "custom" order can never be smaller, on any dimension, than this family's own
310	 * biggest premade tier.
311	 *
312	 * Still gated (throws) for a family with ZERO live tiers to anchor from at all —
313	 * see `customGamePlanRates`'s doc and lib/custom-plan-pricing.ts's derivation
314	 * comment for exactly which families that is and why (as of 2026-09-29:
315	 * `schedule1` and the four `plutonium*` variants — none of which can be bought as a
316	 * premade tier either today, so this changes nothing about their sellability).
317	 */
318	export async function createCustomGamePlan(opts: {
319	  spec: CustomPlanSpec;
320	  gameFamily: string;
321	  players?: number | null;
322	}): Promise<CreatedCustomGamePlan> {
323	  const topTier = await db.gamePlan.findFirst({
324	    where: { gameFamily: opts.gameFamily, active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
325	    orderBy: { priceCents: "desc" },
326	  });
327	  if (!topTier) {
328	    throw new CustomPlanError(
329	      "Custom-sized servers for this game aren't available yet — there's no pricing catalog to build a custom quote from. Please contact support.",
330	    );
331	  }
332	  const anchor: CustomGamePlanAnchor = {
333	    cpuCores: topTier.cpuCores,
334	    ramMB: topTier.ramMB,
335	    diskGB: topTier.diskGB,
336	    priceCents: topTier.priceCents,
337	  };
338	
339	  const [vpsFloor, ceiling, gameRates] = await Promise.all([
340	    customPlanFloor(),
341	    customPlanCeiling(),
342	    customGamePlanRates(opts.gameFamily),
343	  ]);
344	  if (!gameRates) {
345	    throw new CustomPlanError(
346	      "Custom-sized servers for this game aren't available yet — please contact support for a custom quote.",
347	    );
348	  }
349	
350	  const floor = gameCustomFloor(vpsFloor, anchor);
351	  const v = validateCustomPlanSpec(opts.spec, floor, ceiling);
352	  if (!v.ok) throw new CustomPlanError(v.reason);
353	  const cap = await customPlanCapacityCheck(opts.spec);
354	  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");
355	
356	  const priceCents = computeCustomGamePlanPriceCents(opts.spec, anchor, gameRates.rates, vpsFloor.priceCents);
357	  const plan = await createCustomPlanRow(opts.spec, priceCents, vpsFloor.bandwidthTB);
358	  const gp = await db.gamePlan.create({
359	    data: {
360	      gameFamily: opts.gameFamily,
361	      name: `${customPlanName(opts.spec)} (${opts.gameFamily})`,
362	      ramMB: plan.ramMB,
363	      cpuCores: plan.cpuCores,
364	      diskGB: plan.diskGB,
365	      slots: opts.players ?? null,
366	      priceCents: plan.priceCents,
367	      termMonths: 1,
368	      basePlanId: plan.id,
369	      active: false,
370	      sortOrder: CUSTOM_PLAN_SORT_ORDER,
371	    },
372	  });
373	  return { plan, gamePlanId: gp.id, name: gp.name, priceCents: gp.priceCents, slots: gp.slots };
374	}
