---
package.json:68:    "playwright": "^1.62.1",

1	/**
2	 * E2E test: creates a test customer, funds the wallet, orders a VPS
3	 * (same DB operations the orderServer action performs), then waits for
4	 * the worker to provision it and prints connection details.
5	 */
6	import { PrismaClient } from "@prisma/client";
7	import bcrypt from "bcryptjs";
8	
9	const db = new PrismaClient();
10	
11	async function main() {
12	  const email = "e2e-test@nxeon.local";
13	  let user = await db.user.findUnique({ where: { email } });
14	  if (!user) {
15	    user = await db.user.create({
16	      data: {
17	        email,
18	        name: "E2E Test",
19	        passwordHash: await bcrypt.hash("e2e-test-password", 12),
20	        balanceCents: 1000,
21	      },
22	    });
23	  }
24	
25	  const plan = await db.plan.findUnique({ where: { slug: "nano" } });
26	  const os = await db.osTemplate.findUnique({ where: { slug: "ubuntu-24-04" } });
27	  if (!plan || !os) throw new Error("seed data missing");
28	
29	  const server = await db.$transaction(async (tx) => {
30	    await tx.user.update({ where: { id: user!.id }, data: { balanceCents: { decrement: plan.priceCents } } });
31	    await tx.walletTransaction.create({
32	      data: { userId: user!.id, amountCents: -plan.priceCents, description: "E2E order" },
33	    });
34	    // Server.hostname is globally unique (see its schema comment) — re-running
35	    // this script against a non-empty DB used to insert a second row literally
36	    // named "e2e-test" every time; now that the constraint exists, that would
37	    // just throw. A short random suffix per run keeps this script repeatable
38	    // without needing its own collision-check query.
39	    const hostname = `e2e-test-${Math.random().toString(36).slice(2, 8)}`;
40	    const s = await tx.server.create({
41	      data: {
42	        name: hostname,
43	        hostname,
44	        userId: user!.id,
45	        planId: plan.id,
46	        osTemplateId: os.id,
47	        expiresAt: new Date(Date.now() + 30 * 86400_000),
48	      },
49	    });
50	    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
51	    return s;
52	  });
53	
54	  console.log(`ordered server ${server.id}, waiting for worker...`);
55	  const deadline = Date.now() + 10 * 60_000;
56	  for (;;) {
57	    const s = await db.server.findUnique({ where: { id: server.id } });
58	    if (!s) throw new Error("server vanished");
59	    process.stdout.write(`  status=${s.status} vmid=${s.vmid ?? "-"}\r`);
60	    if (s.status === "RUNNING") {
61	      console.log(`\nRESULT ip=${s.ipAddress} sshPort=${s.sshPort} password=${s.rootPassword} vmid=${s.vmid}`);
62	      break;
63	    }
64	    if (s.status === "ERROR") {
65	      const job = await db.job.findFirst({ where: { serverId: s.id }, orderBy: { createdAt: "desc" } });
66	      throw new Error(`provisioning failed: ${job?.error}`);
67	    }
68	    if (Date.now() > deadline) throw new Error("timeout");
69	    await new Promise((r) => setTimeout(r, 5000));
70	  }
71	}
72	
73	main().finally(() => db.$disconnect());
