46	/** Cheapest real custom build: one unit over the floor on the cheapest
47	 *  dimension — through the same formula, so "from $X" is never a guess. */
48	function minCustomPriceCents(cfg: CustomPlanConfig): number {
49	  const f = cfg.floor;
50	  const base = { cpuCores: f.cpuCores, ramMB: f.ramMB, diskGB: f.diskGB };
51	  return Math.min(
52	    computeCustomPlanPriceCents({ ...base, cpuCores: base.cpuCores + 1 }, f, cfg.rates),
53	    computeCustomPlanPriceCents({ ...base, ramMB: base.ramMB + 1024 }, f, cfg.rates),
54	    computeCustomPlanPriceCents({ ...base, diskGB: base.diskGB + DISK_STEP_GB }, f, cfg.rates),
55	  );
56	}
