64	 *  players slider and stated as exactly what it is — the setting's range —
65	 *  rather than claimed as a hard engine limit. */
66	export function engineMaxPlayers(fields: ConfigField[] | undefined): number | null {
67	  const f = (fields ?? []).find((x) => x.type === "int" && /max\s*players?/i.test(x.label) && typeof x.max === "number");
68	  return f?.max ?? null;
69	}
