109	        {!built && <span className="text-[11.5px] text-tx-dim">from</span>}
110	        <span className="num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[25px] text-transparent">
111	          {money(builtMonthly ?? from)}
112	        </span>
