185	            {atMax ? "Self-serve max" : extra > 0 ? `+${money(extra * rateCents)}/mo` : "Included"}
186	          </span>
187	        </span>
188	      </div>
189	      <input type="range" aria-label={`${label} (${unit})`}
190	             min={min} max={max} step={step} value={value}
