199	type QuoteState =
200	  | { key: string; status: "checking" }
201	  | { key: string; status: "ok"; priceCents: number; termMonthlyCents: Record<number, number>; capacityOk: boolean; capacityReason?: string }
202	  | { key: string; status: "bad"; reason: string };
