204	export function CustomServerBuilder({ cfg, kind, family, familyName, checkoutFields, terms, onBuilt, onClose }: {
205	  cfg: CustomPlanConfig;
206	  kind: "vps" | "game";
207	  /** Game orders only. */
208	  family?: string;
209	  familyName?: string;
210	  checkoutFields?: ConfigField[];
211	  terms: TermOption[];
212	  /** Called after the custom row exists and has been selected. */
213	  onBuilt: () => void;
214	  onClose: () => void;
215	}) {
216	  const { o, cat, applyCustomPlan, applyCustomTier } = useOrder();
217	  const money = useMoney();
218	  const { floor, ceiling, rates } = cfg;
219	  const isGame = kind === "game" && !!family;
220	
221	  // Start from the build already made this session, if there is one, so
222	  // "Edit custom build" reopens on what the customer chose — not a reset.
223	  const existing: (PlanOption | GameTier) | null = isGame
224	    ? cat.games.find((g) => g.family === family)?.tiers.find((t) => t.custom) ?? null
225	    : cat.plans.find((p) => p.custom) ?? null;
226	
227	  const engineMax = isGame ? engineMaxPlayers(checkoutFields) : null;
228	  const sliderMax = isGame
229	    ? Math.max(2, Math.min(playerSliderMax(family as GameFamily), engineMax ?? Infinity))
230	    : 0;
231	
232	  /* Round a recommendation onto the sliders' own grid (whole GB of RAM, 10 GB
233	     of disk above the floor) and clamp into floor..ceiling. If that lands on
234	     the floor exactly — i.e. the headcount fits a standard plan — nudge RAM up
235	     1 GB so the spec is a real custom build (a floor-identical spec is just
236	     "Max" and the server rightly refuses it). */
237	  const fromPlayers = (players: number): { spec: CustomPlanSpec; overCeiling: boolean; fitsStandard: boolean } => {
238	    const rec = recommendedSpecForPlayers(family as GameFamily, players);
239	    const raw: CustomPlanSpec = {
240	      cpuCores: rec.cpuCores,
241	      ramMB: Math.ceil(rec.ramMB / 1024) * 1024,
242	      diskGB: floor.diskGB + Math.ceil(Math.max(0, rec.diskGB - floor.diskGB) / DISK_STEP_GB) * DISK_STEP_GB,
243	    };
244	    const overCeiling = raw.cpuCores > ceiling.maxCpuCores || raw.ramMB > ceiling.maxRamMB || raw.diskGB > ceiling.maxDiskGB;
245	    const fitsStandard = raw.cpuCores <= floor.cpuCores && raw.ramMB <= floor.ramMB && raw.diskGB <= floor.diskGB;
246	    let spec = clampCustomPlanSpec(raw, floor, ceiling);
247	    if (spec.cpuCores === floor.cpuCores && spec.ramMB === floor.ramMB && spec.diskGB === floor.diskGB) {
248	      spec = clampCustomPlanSpec({ ...spec, ramMB: spec.ramMB + 1024 }, floor, ceiling);
249	    }
250	    return { spec, overCeiling, fitsStandard };
251	  };
252	
253	  const initialPlayers = isGame
254	    ? (existing && "slots" in existing && existing.slots ? Math.min(existing.slots, sliderMax) : Math.max(1, Math.round(sliderMax / 2)))
255	    : 0;
256	  const [players, setPlayers] = useState<number>(initialPlayers);
257	  const [spec, setSpec] = useState<CustomPlanSpec>(() => {
258	    if (existing) return { cpuCores: existing.cpuCores, ramMB: existing.ramMB, diskGB: existing.diskGB };
259	    if (isGame) return fromPlayers(initialPlayers).spec;
260	    // VPS: open one clear step up from the top plan (double it), not on the
261	    // floor itself — the floor alone is just "Max" and can't be ordered here.
262	    return clampCustomPlanSpec(
263	      { cpuCores: floor.cpuCores * 2, ramMB: floor.ramMB * 2, diskGB: floor.diskGB * 2 }, floor, ceiling);
264	  });
265	  const playerInfo = isGame ? fromPlayers(players) : null;
266	
267	  const setPlayersAndSpec = (n: number) => {
268	    setPlayers(n);
269	    setSpec(fromPlayers(n).spec);
270	  };
271	  const setDim = (k: keyof CustomPlanSpec, v: number) =>
272	    setSpec((s) => clampCustomPlanSpec({ ...s, [k]: v }, floor, ceiling));
273	
274	  const specKey = `${spec.cpuCores}/${spec.ramMB}/${spec.diskGB}`;
275	  const valid = validateCustomPlanSpec(spec, floor, ceiling);
276	  const preview = computeCustomPlanPriceCents(spec, floor, rates);
277	
278	  /* The authoritative check, debounced behind the slider. Keyed by spec so a
279	     slow reply for a spec the customer has already moved past is ignored. */
280	  const [quote, setQuote] = useState<QuoteState | null>(null);
281	  useEffect(() => {
282	    if (!valid.ok) { setQuote(null); return; }
283	    let cancelled = false;
284	    const key = specKey;
285	    setQuote({ key, status: "checking" });
286	    const t = setTimeout(async () => {
287	      try {
288	        const res = await quoteCustomPlanAction(spec);
289	        if (cancelled) return;
290	        if (!res.ok || res.priceCents == null) setQuote({ key, status: "bad", reason: res.error ?? "That configuration isn't available." });
291	        else setQuote({
292	          key, status: "ok", priceCents: res.priceCents,
293	          termMonthlyCents: res.termMonthlyCents ?? {},
294	          capacityOk: !!res.capacityOk, capacityReason: res.capacityReason,
295	        });
296	      } catch {
297	        if (!cancelled) setQuote({ key, status: "bad", reason: "Couldn't check that right now — try again in a moment." });
298	      }
299	    }, 450);
300	    return () => { cancelled = true; clearTimeout(t); };
301	    // eslint-disable-next-line react-hooks/exhaustive-deps
302	  }, [specKey, valid.ok]);
303	  const current = quote && quote.key === specKey ? quote : null;
304	  const confirmedPrice = current?.status === "ok" ? current.priceCents : null;
305	  const capacityBad = current?.status === "ok" && !current.capacityOk;
306	  const canContinue = valid.ok && current?.status === "ok" && current.capacityOk;
307	
308	  const [busy, setBusy] = useState(false);
309	  const [err, setErr] = useState<string | null>(null);
310	  async function build() {
