317	          // RECOMMENDED player count (GamePlan.slots), never enforced as a cap.
318	          ...spec, gameFamily: family!, players,
319	        });
320	        if (!res.ok || !res.tier) { setErr(res.error ?? "Couldn't set up that custom server."); return; }
