326	          name: `Custom · ${t.cpuCores} vCPU / ${gb(t.ramMB)} GB`,
327	          ramMB: t.ramMB, cpuCores: t.cpuCores, diskGB: t.diskGB,
328	          slots: t.slots,
329	          monthlyCents: t.priceCents,
330	          termMonths: t.termMonths,
331	          introMonthlyCents: null, introRenewalMonthlyCents: null,
332	          termMonthlyCents: t.termMonthlyCents,
333	        });
334	      } else {
335	        const res = await confirmCustomPlanAction(spec);
336	        if (!res.ok || !res.plan) { setErr(res.error ?? "Couldn't set up that custom server."); return; }
337	        const p = res.plan;
338	        applyCustomPlan({
339	          id: p.id, slug: "custom", name: `Custom · ${p.cpuCores} vCPU / ${gb(p.ramMB)} GB`,
340	          cpuCores: p.cpuCores, ramMB: p.ramMB, diskGB: p.diskGB, bandwidthTB: p.bandwidthTB,
341	          monthlyCents: p.priceCents,
