361	    : capacityBad ? (current?.status === "ok" ? current.capacityReason ?? "We don't have room for this size right now." : null)
362	    : atAnyMax ? "You're at our self-serve maximum on at least one resource."
363	    : null;
364	
365	  const salesHref = useMemo(() => {
366	    const lines = [
367	      "Custom server request (from the deploy wizard)",
368	      `Product: ${isGame ? `Game server — ${familyName ?? family}` : "Cloud VPS"}`,
369	      ...(isGame ? [`Players: ~${players}`] : []),
370	      `Spec I was looking at: ${spec.cpuCores} vCPU / ${gb(spec.ramMB)} GB RAM / ${spec.diskGB} GB disk`,
371	      `Billing term: ${terms.find((t) => t.months === o.termMonths)?.label ?? `${o.termMonths} months`}`,
372	      ...(salesReason ? [`Note: ${salesReason}`] : []),
