374	      "What I need: ",
375	    ];
376	    return `/contact?topic=custom&message=${encodeURIComponent(lines.join("\n"))}`;
377	  }, [isGame, familyName, family, players, spec, terms, o.termMonths, salesReason]);
378	
379	  const extraCpu = Math.max(0, spec.cpuCores - floor.cpuCores);
380	  const extraRamGb = Math.max(0, gb(spec.ramMB - floor.ramMB));
381	  const extraDisk = Math.max(0, spec.diskGB - floor.diskGB);
382	  const shownPrice = confirmedPrice ?? preview;
383	  const termLabel = terms.find((t) => t.months === o.termMonths)?.label ?? "";
384	  const termMonthly = current?.status === "ok" ? current.termMonthlyCents[o.termMonths] : undefined;
385	
386	  return (
387	    <div className="card flex flex-col gap-4 p-4" id="custom-builder">
