      orderBy: { priceCents: "desc" },
    }),
    customPlanFloor(),
    customPlanCeiling(),
  ]);
  if (!topTier) {
    return {
      ok: false,
      reason: "Custom-sized servers for this game aren't available yet — there's no pricing catalog to build a custom quote from. Please contact support.",
