    // estimatedGameFamilyRamRateCents's own comment. Logged here (not just in
    // createCustomGamePlan) so an admin notices the moment a QUOTE, not only a
    // real order, starts leaning on a genre-average guess.
    console.warn(`[custom-plan] ${gameFamily} quoted with an ESTIMATED RAM rate (${gameRates.basis})`);
  }
  const priceCents = computeCustomGamePlanPriceCents(spec, anchor, gameRates.rates, vpsFloor.priceCents);
  return { ok: true, floor, ceiling, rates: gameRates.rates, priceCents };
}

