/**
 * The GAME analogue of `CustomPlanConfig` — one per game family
 * (`GameFamilyOption.customPlan`), NOT the shared VPS one above.
 *
 * `floor`/`ceiling`/`rates` mean what they do on `CustomPlanConfig`: `floor`'s
 * cpu/ram/diskGB are the SLIDER BOUNDS (componentwise-max(VPS Max, this
 * family's own top tier) — `gameCustomFloor`, lib/custom-plan-pricing.ts) and
 * `rates` is this family's own derived $/vCPU-$/RAM-GB-$/disk-GB rate.
 *
 * `floor.priceCents` here is deliberately NOT meaningful on its own (unlike the
 * VPS config, where `computeCustomPlanPriceCents` adds the rate straight onto
 * `floor.priceCents`) — a game's price is anchored to `anchor` (this family's
 * own real top tier) and evaluated through `computeCustomGamePlanPriceCents`,
 * not through the flat `floor.price + rate*(spec-floor)` formula. Reusing that
 * generic formula with `floor.priceCents` swapped in for a game would only be
 * correct exactly AT the floor spec and increasingly overstate the true price
 * as the spec grows for any family whose floor price is clamped up to the VPS
 * anti-undercut minimum (roughly a quarter of the catalog) — hence the
 * separate `anchor` + `vpsFloorPriceCents` fields and the separate formula.
 */
export type GameCustomPlanConfig = {
  floor: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number; bandwidthTB: number };
  ceiling: { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
  rates: { perVcpuCents: number; perRamGbCents: number; perDiskGbCents: number };
  /** This family's own real top tier — the point `computeCustomGamePlanPriceCents`
   *  extends its price curve from. */
  anchor: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number };
  /** The platform VPS-Max price — the anti-undercut clamp floor
   *  `computeCustomGamePlanPriceCents` never prices strictly at-or-below. */
  vpsFloorPriceCents: number;
};

