import type { CustomPlanConfig, GameCustomPlanConfig, GameTier, PlanOption, TermOption } from "./order-types";
import type { ConfigField } from "@/lib/game-config";
import {
  clampCustomPlanSpec,
  computeCustomGamePlanPriceCents,
  computeCustomPlanPriceCents,
  validateCustomPlanSpec,
  type CustomPlanSpec,
} from "@/lib/custom-plan-pricing";
import { playerSliderMax, recommendedSpecForPlayers } from "@/lib/game-player-recommend";
import type { GameFamily } from "@/lib/games";
import {
  confirmCustomGamePlanAction,
  confirmCustomPlanAction,
  quoteCustomGamePlanAction,
  quoteCustomPlanAction,
} from "@/lib/actions-custom-plan";

/** True when `cfg` is a per-family GAME config (carries `anchor`), not the
 *  shared VPS one — narrows the union so the right price formula/quote action
 *  gets used below. */
function isGameCfg(cfg: CustomPlanConfig | GameCustomPlanConfig): cfg is GameCustomPlanConfig {
  return "anchor" in cfg;
}

/** The instant, no-round-trip preview price for `spec` under `cfg` — the VPS
 *  formula (floor + rate×extra) for a VPS config, or the family-curve formula
 *  (this family's own top tier + rate×extra beyond it, anti-undercut clamped)
 *  for a game config. See GameCustomPlanConfig's own doc for why these are NOT
 *  interchangeable — reusing the VPS formula with a game's floor swapped in
 *  would overstate the price more and more as the spec grows past the floor
 *  for any family whose floor price is anti-undercut-clamped. */
function previewPriceCents(spec: CustomPlanSpec, cfg: CustomPlanConfig | GameCustomPlanConfig): number {
  return isGameCfg(cfg)
    ? computeCustomGamePlanPriceCents(spec, cfg.anchor, cfg.rates, cfg.vpsFloorPriceCents)
    : computeCustomPlanPriceCents(spec, cfg.floor, cfg.rates);
}

