/**
 * REAL verification script for the custom-game-plan per-family pricing fix.
 * Run from /opt/nxeon-staging with `npx tsx scratch-verify-custom-game-pricing.ts`.
 *
 * For Rust, Minecraft and Squad:
 *   1. customGamePlanQuote()  -- real DB-backed quote (family rate + widened floor)
 *   2. createCustomGamePlan() -- REALLY creates the one-off Plan+GamePlan rows
 *   3. A REAL Stripe TEST-MODE PaymentIntent for exactly the quoted amount,
 *      confirmed with Stripe's documented 4242-Visa test PaymentMethod
 *      (pm_card_visa) -- a genuine test-mode charge, not a simulation.
 *   4. Credits the test user's wallet by that exact charged amount (mirrors a
 *      real top-up-then-spend flow) and places a REAL order through
 *      gameOrderQuote + placeGameOrder -- a real Server + Job(PROVISION) row.
 *   5. For Minecraft only (representative full pipeline check): polls the
 *      worker until the server is RUNNING, then deletes it via a real
 *      Job(DELETE) row and confirms it's gone.
 *   6. Rust/Squad: deletes the one-off Plan/GamePlan rows directly afterward
 *      (no Server ever referenced them, so nothing to tear down via a job).
 *
 * Also verifies a PLAIN VPS custom order (createCustomPlan) still prices at
 * the old flat VPS rate, untouched by this change, with its own real Stripe
 * charge, then deletes the one-off Plan row directly.
 */
import Stripe from "stripe";
import bcrypt from "bcryptjs";
import { db } from "./lib/db";
import { customGamePlanQuote, createCustomGamePlan, customPlanQuote, createCustomPlan, customPlanFloor } from "./lib/custom-plan";
import { gameOrderQuote, placeGameOrder } from "./lib/game-order";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

function fmt(cents: number) {
  return `$${(cents / 100).toFixed(2)}`;
}

async function realStripeCharge(amountCents: number, label: string) {
  const pi = await stripe.paymentIntents.create({
    amount: amountCents,
    currency: "usd",
    payment_method: "pm_card_visa", // Stripe's documented test PM for 4242 4242 4242 4242
    payment_method_types: ["card"],
    confirm: true,
    description: `nxeon custom-game-pricing verification: ${label}`,
  });
  return pi;
}

async function main() {
  const email = "custom-game-pricing-verify@nxeon.local";
  let user = await db.user.findUnique({ where: { email } });
  if (!user) {
    user = await db.user.create({
      data: { email, name: "Custom Pricing Verify", passwordHash: await bcrypt.hash("verify-test-pw", 12), balanceCents: 0 },
    });
  } else {
    user = await db.user.update({ where: { id: user.id }, data: { balanceCents: 0 } });
  }
  console.log(`test user: ${user.id} (${email})`);

  const results: Record<string, unknown> = {};

  // ── plain VPS control (unaffected by this change) ──────────────────────
  {
    console.log("\n=== VPS CONTROL (createCustomPlan, must be unaffected) ===");
    const floor = await customPlanFloor();
    const spec = { cpuCores: floor.cpuCores + 2, ramMB: floor.ramMB + 5 * 1024, diskGB: floor.diskGB + 20 };
    const quote = await customPlanQuote(spec);
    if (!quote.ok) throw new Error(`VPS quote failed: ${JSON.stringify(quote)}`);
    const expected = floor.priceCents + 2 * quote.rates.perVcpuCents + 5 * quote.rates.perRamGbCents + 20 * quote.rates.perDiskGbCents;
    console.log(`floor=${JSON.stringify(floor)} rates=${JSON.stringify(quote.rates)}`);
    console.log(`quoted=${fmt(quote.priceCents)} handCalc(oldFlatFormula)=${fmt(expected)} match=${quote.priceCents === Math.max(expected, floor.priceCents + 1)}`);
    const created = await createCustomPlan(spec);
    console.log(`created plan ${created.id} price=${fmt(created.priceCents)} match-quote=${created.priceCents === quote.priceCents}`);
    const pi = await realStripeCharge(created.priceCents, "VPS control");
    console.log(`STRIPE charge: id=${pi.id} status=${pi.status} amount=${fmt(pi.amount)} match=${pi.amount === created.priceCents}`);
    await db.plan.delete({ where: { id: created.id } });
    console.log(`cleaned up plan ${created.id}`);
    results.vpsControl = { quoted: quote.priceCents, created: created.priceCents, stripeAmount: pi.amount, stripeStatus: pi.status, rates: quote.rates, floor };
  }

  // ── game families ────────────────────────────────────────────────────
  const cases: { family: string; spec: { cpuCores: number; ramMB: number; diskGB: number }; players: number; region: string; needsSubdomain?: boolean }[] = [
    { family: "rust", spec: { cpuCores: 10, ramMB: 23 * 1024, diskGB: 120 }, players: 200, region: "sgp1" },
    { family: "minecraft", spec: { cpuCores: 6, ramMB: 23 * 1024, diskGB: 130 }, players: 60, region: "sgp1", needsSubdomain: true },
    { family: "squad", spec: { cpuCores: 15, ramMB: 42 * 1024, diskGB: 125 }, players: 120, region: "sgp1" },
  ];

  for (const c of cases) {
    console.log(`\n=== GAME FAMILY: ${c.family} ===`);
    const topTierBefore = await db.gamePlan.findFirst({
      where: { gameFamily: c.family, active: true, sortOrder: { lt: 900 } },
      orderBy: { priceCents: "desc" },
    });
    console.log(`family's own top real tier: ${topTierBefore?.name} = ${fmt(topTierBefore?.priceCents ?? -1)}`);

    const quote = await customGamePlanQuote(c.family, c.spec);
    if (!quote.ok) throw new Error(`${c.family} quote failed: ${JSON.stringify(quote)}`);
    console.log(`floor(widened)=${JSON.stringify(quote.floor)}`);
    console.log(`rates=${JSON.stringify(quote.rates)}`);
    console.log(`QUOTED price for spec ${JSON.stringify(c.spec)}: ${fmt(quote.priceCents)}`);
    console.log(`monotonic vs family top tier (${fmt(topTierBefore!.priceCents)}): ${quote.priceCents > topTierBefore!.priceCents}`);

    const created = await createCustomGamePlan({ spec: c.spec, gameFamily: c.family, players: c.players });
    console.log(`CREATED gamePlanId=${created.gamePlanId} price=${fmt(created.priceCents)} match-quote=${created.priceCents === quote.priceCents}`);

    const pi = await realStripeCharge(created.priceCents, `${c.family} custom build`);
    console.log(`STRIPE charge: id=${pi.id} status=${pi.status} amount=${fmt(pi.amount)} match=${pi.amount === created.priceCents}`);

    (results as any)[c.family] = {
      topTierBefore: topTierBefore?.priceCents,
      quoted: quote.priceCents,
      created: created.priceCents,
      stripeAmount: pi.amount,
      stripeStatus: pi.status,
      rates: quote.rates,
      floor: quote.floor,
    };

    if (c.family === "minecraft") {
      // Full real pipeline: credit wallet by the charged amount, place a real
      // order, wait for the worker to provision it, then delete it for real.
      await db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: pi.amount } } });
      const intent = {
        gamePlanId: created.gamePlanId,
        termMonths: 1,
        hostname: `verify-mc-${Math.random().toString(36).slice(2, 8)}`,
        subdomain: `verifymc${Math.random().toString(36).slice(2, 8)}`,
        region: c.region,
      };
      const oq = await gameOrderQuote(intent, { userId: user.id });
      console.log(`gameOrderQuote chargeCents=${fmt(oq.chargeCents)} (should equal created price, no promo applies to games): match=${oq.chargeCents === created.priceCents}`);
      const serverId = await placeGameOrder(user, intent);
      console.log(`placeGameOrder -> serverId=${serverId}`);
      (results as any).minecraft.orderChargeCents = oq.chargeCents;
      (results as any).minecraft.serverId = serverId;

      const deadline = Date.now() + 8 * 60_000;
      let finalStatus = "UNKNOWN";
      for (;;) {
        const s = await db.server.findUnique({ where: { id: serverId } });
        if (!s) { finalStatus = "VANISHED"; break; }
        process.stdout.write(`  status=${s.status} vmid=${s.vmid ?? "-"}\r`);
        if (s.status === "RUNNING" || s.status === "ERROR") { finalStatus = s.status; break; }
        if (Date.now() > deadline) { finalStatus = `TIMEOUT(last=${s.status})`; break; }
        await new Promise((r) => setTimeout(r, 5000));
      }
      console.log(`\nprovisioning result: ${finalStatus}`);
      (results as any).minecraft.provisionResult = finalStatus;

      // Tear down via the normal DELETE flow.
      await db.job.create({ data: { type: "DELETE", serverId } });
      const delDeadline = Date.now() + 5 * 60_000;
      let deleted = false;
      for (;;) {
        const s = await db.server.findUnique({ where: { id: serverId } });
        if (!s) { deleted = true; break; }
        process.stdout.write(`  delete status=${s.status}\r`);
        if (Date.now() > delDeadline) break;
        await new Promise((r) => setTimeout(r, 5000));
      }
      console.log(`\ndeleted via DELETE job: ${deleted}`);
      (results as any).minecraft.deleted = deleted;
    } else {
      // No Server was ever created for this one — safe to remove the one-off
      // rows directly.
      await db.gamePlan.delete({ where: { id: created.gamePlanId } });
      await db.plan.delete({ where: { id: created.plan.id } });
      console.log(`cleaned up gamePlan ${created.gamePlanId} + plan ${created.plan.id}`);
    }
  }

  console.log("\n\n=== FULL RESULTS JSON ===");
  console.log(JSON.stringify(results, null, 2));
}

main()
  .catch((e) => { console.error("FATAL:", e); process.exitCode = 1; })
  .finally(() => db.$disconnect());

